const ReadContentActivation = `WITH a AS (
  SELECT revision_id, activation_version, activated_at, activated_by
  FROM gxb_content_activation WHERE slot='content'
)
SELECT EXISTS(SELECT 1 FROM a) AS exists,
       COALESCE((SELECT revision_id FROM a),'') AS revision_id,
       COALESCE((SELECT activation_version FROM a),0)::bigint AS activation_version,
       COALESCE((SELECT activated_at FROM a),'epoch'::timestamptz) AS activated_at,
       COALESCE((SELECT activated_by FROM a),'') AS activated_by;`

const ReadActiveContentSummary = `WITH a AS (
  SELECT a.revision_id, a.activation_version, a.activated_at, a.activated_by,
         r.schema_version, r.manifest
  FROM gxb_content_activation a
  JOIN gxb_content_revisions r ON r.revision_id=a.revision_id
  WHERE a.slot='content'
)
SELECT EXISTS(SELECT 1 FROM a) AS exists,
       COALESCE((SELECT revision_id FROM a),'') AS revision_id,
       COALESCE((SELECT activation_version FROM a),0)::bigint AS activation_version,
       COALESCE((SELECT activated_at FROM a),'epoch'::timestamptz) AS activated_at,
       COALESCE((SELECT activated_by FROM a),'') AS activated_by,
       COALESCE((SELECT schema_version FROM a),0)::integer AS schema_version,
       COALESCE((SELECT manifest::text FROM a),'{}') AS manifest_json;`

const BootstrapContentActivation = `INSERT INTO gxb_content_activation(slot, revision_id, activation_version, activated_at, activated_by)
VALUES ('content', $1, 1, $2, $3)
ON CONFLICT (slot) DO NOTHING;`

const ActivateContentCAS = `UPDATE gxb_content_activation
SET revision_id=$1, activation_version=activation_version+1, activated_at=$2, activated_by=$3
WHERE slot='content' AND revision_id=$4 AND activation_version=$5;`

const ReadContentResourceByResourceKey = `-- R4D runtime reads are always revision-qualified. Active/current selection is
-- performed once at owning-command admission and never hidden in these queries.
SELECT class,catalog_status,settlement_activation,COALESCE(resource_key,''),COALESCE(item_id,0),
       COALESCE(stack_cap,0),COALESCE(overflow_to_mail,false),COALESCE(regen_seconds,0),
       COALESCE(regen_amount,0),COALESCE(cap_rule,''),COALESCE(static_cap,0),COALESCE(specialized_owner,''),COALESCE(reason,'')
FROM gxb_content_resource_definitions
WHERE revision_id=$1 AND class=$2 AND resource_key=$3;`

const ReadContentResourceByItemID = `SELECT class,catalog_status,settlement_activation,COALESCE(resource_key,''),COALESCE(item_id,0),
       COALESCE(stack_cap,0),COALESCE(overflow_to_mail,false),COALESCE(regen_seconds,0),
       COALESCE(regen_amount,0),COALESCE(cap_rule,''),COALESCE(static_cap,0),COALESCE(specialized_owner,''),COALESCE(reason,'')
FROM gxb_content_resource_definitions
WHERE revision_id=$1 AND item_id=$2;`

const ReadContentPlayerProgressionPolicy = `SELECT COALESCE(jsonb_agg(jsonb_build_object(
  'level',level,'max_energy',max_energy,'award_energy',award_energy,'total_exp',total_exp
) ORDER BY level),'[]'::jsonb)::text
FROM gxb_content_player_progression
WHERE revision_id=$1;`

const ReadContentFunctionGatePolicy = `SELECT COALESCE(jsonb_agg(jsonb_build_object(
  'function_id',function_id,'gate_kind',gate_kind,'required_level',required_level,
  'raw_open_value',raw_open_value,'source_fact_key',source_fact_key,
  'announcement_capability',announcement_capability
) ORDER BY function_id),'[]'::jsonb)::text
FROM gxb_content_function_gates
WHERE revision_id=$1;`

const ReadContentObjectiveDefinition = `SELECT stock_family,strategy,accepted_fact_kind,target,reward_plan::text,huoyue
FROM gxb_content_objective_definitions
WHERE revision_id=$1 AND program_id=$2 AND objective_id=$3 AND definition_revision=$4;`

const ReadContentRevisionManifest = `SELECT manifest::text FROM gxb_content_revisions WHERE revision_id=$1;`
